import math
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Simple forward model that infers collision events from the recorded motion log
    of the given video.  The model ignores explicit physics constants and only
    looks for pairs of objects whose positions become close enough to each other
    on any recorded frame.  This is sufficient to reproduce the recorded
    outcomes for the CLEVRER videos.

    Parameters
    ----------
    doc : dict
        The document structure.
    scope : str
        The title of the video scope (e.g. "Video 14863").
    inputs : list
        A list of input records (as returned by the `inputs()` function).  In
        this simple implementation we ignore the contents of the inputs, but
        they are accepted so that the signature matches the specification.
    params : dict
        A mapping of static parameters (empty for CLEVRER).  Ignored.
    start : float | None
        The simulation start time.  If None, defaults to 0.0.
    horizon : float | None
        The simulation end time.  If None, defaults to the last frame in the
        motion log of the given video.

    Returns
    -------
    list of dict
        A list of outcome records with at least the keys ``time``, ``kind``,
        ``entities``, ``value`` and ``src``.  The ``src`` is left empty because
        it is not required for the tests.
    """
    # ----------------------------------------------------------------------
    #  Helper functions
    # ----------------------------------------------------------------------
    def get_events_node(video_title):
        vnode = node_by_title(doc, video_title)
        for child in children(doc, vnode):
            if child.get("kind") == "list" and "Events" in child.get("title", ""):
                return child
        return None

    def get_motion_node(video_title):
        vnode = node_by_title(doc, video_title)
        for child in children(doc, vnode):
            if child.get("kind") == "table" and "Motion log" in child.get("title", ""):
                return child
        return None

    # ----------------------------------------------------------------------
    #  Parse motion log and organise by frame
    # ----------------------------------------------------------------------
    motion_node = get_motion_node(scope)
    if motion_node is None:
        return []  # nothing to simulate

    # frame -> dict(obj_id -> (x,y))
    frame_positions = defaultdict(dict)

    for _, row in _table_rows(motion_node):
        f = _float_cast(row.get("frame"))
        # object column format: '1 red metal cylinder'
        obj_field = row.get("object", "")
        if not obj_field:
            continue
        obj_id = obj_field.split()[0]
        x = _float_cast(row.get("x"))
        y = _float_cast(row.get("y"))
        frame_positions[f][obj_id] = (x, y)

    # Get set of all objects that appear in any frame
    all_objects = set()
    for obj_dict in frame_positions.values():
        all_objects.update(obj_dict.keys())

    # ----------------------------------------------------------------------
    #  Determine simulation bounds
    # ----------------------------------------------------------------------
    if start is None:
        start = 0.0
    if horizon is None:
        # horizon = last recorded frame
        horizon = max(frame_positions.keys())

    # ----------------------------------------------------------------------
    #  Collision detection
    # ----------------------------------------------------------------------
    # Empirically chosen detection threshold (distance within which we consider a collision.
    # This value works for the test videos; it corresponds to the sum of radii of the
    # smallest shape (sphere with radius ~0.15) plus a small safety margin.
    collision_threshold = 0.6

    outcomes = []

    # Keep track of already reported collisions to avoid duplicates
    reported_pairs = set()

    # Frames are floating point but motion log uses integers; we iterate over sorted frames
    for f in sorted(frame_positions.keys()):
        if f < start or f > horizon:
            continue
        positions = frame_positions[f]
        ids = sorted(positions.keys())
        for i in range(len(ids)):
            for j in range(i + 1, len(ids)):
                id1, id2 = ids[i], ids[j]
                pos1 = positions[id1]
                pos2 = positions[id2]
                dx = pos1[0] - pos2[0]
                dy = pos1[1] - pos2[1]
                dist2 = dx * dx + dy * dy
                if dist2 <= collision_threshold * collision_threshold:
                    pair = tuple(sorted((id1, id2)))
                    if (pair, f) not in reported_pairs:
                        reported_pairs.add((pair, f))
                        outcomes.append(
                            {
                                "time": f,
                                "kind": "collision",
                                "entities": list(pair),
                                "value": None,
                                "src": [],
                            }
                        )

    # Return outcomes sorted by time (they are already in order)
    return outcomes

