import re
from typing import List, Dict, Any, Tuple, Optional

# Helper functions (assumed to be available in the sandbox)
# node_by_title(doc, title)
# node_by_id(doc, node_id)
# children(doc, node)
# table_rows(node) -> [(row_index, {column: cell})]

def _node_by_title(name: str) -> Any:
    """Return the node with the given title (case‑sensitive)."""
    return node_by_title(doc, name)

def _find_scope_children(scope_node: Any) -> List[Any]:
    """Return all immediate child nodes of a scope node."""
    return children(doc, scope_node)

def _parse_object_line(line: str) -> Tuple[str, str]:
    """
    Parse a line from the Objects list.
    Expected format:
        'Object 0: gray rubber cylinder (color=gray, material=rubber, shape=cylinder)'
    Returns: (object_id, description)
    """
    m = re.match(r'Object\s+(\d+):\s*(.+)', line)
    if not m:
        raise ValueError(f"Invalid object line: {line!r}")
    return m.group(1), m.group(2)

def _parse_event_line(line: str) -> Tuple[float, str, Tuple[str, ...],
                                          Optional[Tuple[List[str], str]]]:
    """
    Parse a line from the Events list.
    Returns:
        (frame, kind, involved_ids, extra)
    kind can be 'enter', 'view', 'collision', 'exit'.
    involved_ids is a tuple of object ids that participate.
    extra is None or additional matched groups.
    """
    m = re.match(r'Frame\s+(\d+):\s*(.*)', line)
    if not m:
        raise ValueError(f"Invalid event line: {line!r}")
    frame = float(m.group(1))
    rest = m.group(2)

    # Entrance
    m_enter = re.search(r'Object\s+(\d+)\s+enters the scene', rest)
    if m_enter:
        return frame, 'enter', (m_enter.group(1),), None

    # View
    m_view = re.search(r'Object\s+(\d+)\s+is in view', rest)
    if m_view:
        return frame, 'view', (m_view.group(1),), None

    # Collision
    m_coll = re.search(r'Object\s+(\d+).*?collides with Object\s+(\d+)', rest)
    if m_coll:
        return frame, 'collision', (m_coll.group(1), m_coll.group(2)), None

    # Exit
    m_exit = re.search(r'Object\s+(\d+)\s+exits the scene', rest)
    if m_exit:
        return frame, 'exit', (m_exit.group(1),), None

    # Unknown event
    return frame, 'unknown', tuple(), None

def _find_motion_rows(obj_id: str, motion_node: Any) -> List[Dict[str, str]]:
    """Return all table rows belonging to the specified object."""
    rows = []
    for row_index, row in table_rows(motion_node):
        # Object column format: '1 red metal cylinder'
        obj_col = row.get('object', '')
        if obj_col.startswith(obj_id + ' '):
            rows.append((row_index, row))
    return rows

def _first_row_of_object(obj_id: str, motion_node: Any) -> Tuple[int, Dict[str, str]]:
    """Return the first row (index, dict) for object."""
    rows = _find_motion_rows(obj_id, motion_node)
    if not rows:
        raise ValueError(f"No motion data for object {obj_id}")
    return rows[0]

def _first_row_after_frame(obj_id: str, motion_node: Any, frame: float) -> Tuple[int, Dict[str, str]]:
    """Return the first row for an object after the specified frame."""
    rows = _find_motion_rows(obj_id, motion_node)
    for row_index, row in rows:
        if float(row.get('frame', -1)) >= frame:
            return row_index, row
    raise ValueError(f"Object {obj_id} has no motion data after frame {frame}")

def _parse_float(val: str) -> Optional[float]:
    try:
        return float(val)
    except ValueError:
        return None

def entities(doc: Any, scope: str) -> List[Dict[str, Any]]:
    """Return one entry per object in the given video scope."""
    scope_node = _node_by_title(scope)
    obj_node = None
    for child in _find_scope_children(scope_node):
        if child.get('kind') == 'list' and 'Objects' in child.get('title', ''):
            obj_node = child
            break
    if obj_node is None:
        return []

    ent_list: List[Dict[str, Any]] = []
    for idx, line in enumerate(obj_node.get('lines', [])):
        obj_id, desc = _parse_object_line(line)
        ent_list.append({"id": obj_id, "description": desc})
    return ent_list

def recorded_end(doc: Any, scope: str) -> Optional[float]:
    """Return the last frame present in the motion log of a video."""
    scope_node = _node_by_title(scope)
    motion_node = None
    for child in _find_scope_children(scope_node):
        if child.get('kind') == 'table' and 'Motion log' in child.get('title', ''):
            motion_node = child
            break
    if motion_node is None:
        return None
    max_frame = None
    for _, row in table_rows(motion_node):
        f = _parse_float(row.get('frame', ''))
        if f is not None:
            if max_frame is None or f > max_frame:
                max_frame = f
    return max_frame

def inputs(doc: Any, scope: str) -> List[Dict[str, Any]]:
    """Return a list of input records for the video."""
    scope_node = _node_by_title(scope)
