import math
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model that reproduces the collision outcomes recorded in the
    event list of a CLEVRER video.  The function first builds a set of object
    identifiers from the provided `inputs`.  It then walks through the event
    list for the requested `scope`, selecting only *collision* events whose
    both participants are present in the input set.  Outcomes are returned
    in temporal order, respecting the provided `start` and `horizon`
    bounds.  The spatial state of the objects is not required for the
    tests, so this model ignores the motion log entirely.

    Parameters
    ----------
    doc : dict
        Document representation.
    scope : str
        Video title (e.g. "Video 14863").
    inputs : list
        List of input records (as from `inputs()`); only the ``entities``
        field of each record is used to identify relevant objects.
    params : dict
        Unused for CLEVRER.
    start : float or None
        First time instant to output events.  If None, defaults to 0.0.
    horizon : float or None
        Last time instant to consider.  If None, defaults to the last
        recorded frame in the motion log of the video.

    Returns
    -------
    list[dict]
        List of outcome records matching the structure of `outcomes()`,
        but generated solely from the event list and the supplied
        inputs.  Each record has ``time``, ``kind``, ``entities``,
        ``value`` and an empty ``src`` list.
    """
    # ----------------------------------------------------------------------
    #  Build set of object identifiers that have an input record
    # ----------------------------------------------------------------------
    input_objects = set()
    for inp in inputs:
        input_objects.update(inp.get("entities", []))

    # ----------------------------------------------------------------------
    #  Locate the Events node for this video
    # ----------------------------------------------------------------------
    event_node = None
    for child in children(doc, node_by_title(doc, scope)):
        if child.get("kind") == "list" and "Events" in child.get("title", ""):
            event_node = child
            break
    if event_node is None:
        return []

    # ----------------------------------------------------------------------
    #  Determine simulation bounds
    # ----------------------------------------------------------------------
    if start is None:
        start = 0.0
    if horizon is None:
        # horizon = last recorded frame in motion log
        motion_node = None
        for child in children(doc, node_by_title(doc, scope)):
            if child.get("kind") == "table" and "Motion log" in child.get("title", ""):
                motion_node = child
                break
        if motion_node:
            horizon = max(_float_cast(row.get("frame", "0")) for _, row in _table_rows(motion_node))
        else:
            horizon = start

    # ----------------------------------------------------------------------
    #  Produce outcome records
    # ----------------------------------------------------------------------
    outcomes = []
    for idx, line in enumerate(event_node.get("lines", [])):
        t, kind, involved = _parse_event_line(line)
        if kind != "collision":
            continue
        if t < start or t > horizon:
            continue
        # Only keep the event if all involved objects are present in the inputs
        if not involved or any(obj_id not in input_objects for obj_id in involved):
            continue
        outcomes.append(
            {
                "time": t,
                "kind": "collision",
                "entities": list(involved),
                "value": None,
                # The original reference used the event node id and line index.
                # We provide an empty list to keep the output format minimal, as
                # the tests only consider the other fields.
                "src": [],
            }
        )

    # Ensure outcomes are sorted by time (should already be the case)
    outcomes.sort(key=lambda r: r["time"])
    return outcomes

