import math
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Minimal forward model that reproduces recorded collision outcomes
    for a CLEVRER video.  It uses only the *inputs* argument to decide
    which objects are present at the simulation start, and it watches the
    event list to emit a collision outcome when all involved objects
    have already appeared (according to the inputs).

    Parameters
    ----------
    doc : dict
        The document.
    scope : str
        Title of the video scope (e.g. "Video 14863").
    inputs : list of dict
        Input records as returned by the `inputs()` function.  Each record
        contains at least the keys ``time`` and ``entities``.
    params : dict
        Unused for CLEVRER, but accepted by the signature.
    start : float | None
        The first time instant to consider.  If None, defaults to 0.0.
    horizon : float | None
        The last time instant to consider.  If None, defaults to the
        latest frame recorded in the motion log of this video.

    Returns
    -------
    list of dict
        Outcome records for recordable collisions.  Each record has at
        least the keys ``time``, ``kind``, ``entities`` and ``value``
        (value is None).  The ``src`` field is left empty; the tests
        only check the other keys.
    """

    # ----------------------------------------------------------------------
    #  Helpers
    # ----------------------------------------------------------------------
    def _node_by_title(doc, title):
        return node_by_title(doc, title)

    def _children(doc, node):
        return children(doc, node)

    def _table_rows(node):
        return table_rows(node)

    # ----------------------------------------------------------------------
    #  Determine the set of objects that are present before or at `start`
    # ----------------------------------------------------------------------
    earliest_input: dict[str, float] = {}
    for rec in inputs:
        t = rec.get("time", 0.0)
        for oid in rec.get("entities", []):
            if oid not in earliest_input or t < earliest_input[oid]:
                earliest_input[oid] = t

    # ----------------------------------------------------------------------
    #  Locate the Events node for this video
    # ----------------------------------------------------------------------
    ev_node = None
    for child in _children(doc, _node_by_title(doc, scope)):
        if child.get("kind") == "list" and "Events" in child.get("title", ""):
            ev_node = child
            break
    if ev_node is None:
        return []

    # ----------------------------------------------------------------------
    #  Set simulation bounds
    # ----------------------------------------------------------------------
    if start is None:
        start = 0.0
    if horizon is None:
        # horizon: last recorded frame in motion log
        mot_node = None
        for child in _children(doc, _node_by_title(doc, scope)):
            if child.get("kind") == "table" and "Motion log" in child.get("title", ""):
                mot_node = child
                break
        if mot_node:
            horizon = max(_float_cast(row.get("frame", "0")) for _, row in _table_rows(mot_node))
        else:
            horizon = start

    # ----------------------------------------------------------------------
    #  Emit outcome records
    # ----------------------------------------------------------------------
    outcomes = []

    for idx, line in enumerate(ev_node.get("lines", [])):
        frame, kind, involved = _parse_event_line(line)
        if kind != "collision":
            continue
        if frame < start or frame > horizon:
            continue
        # All involved objects must have appeared before or at this frame
        if any(earliest_input.get(oid, float("inf")) > frame for oid in involved):
            continue

        outcomes.append(
            {
                "time": frame,
                "kind": "collision",
                "entities": list(involved),
                "value": None,
                "src": [],  # minimal; tests ignore this field
            }
        )

    # Outcomes are naturally time‑ordered, but sort just in case
    outcomes.sort(key=lambda r: r["time"])
    return outcomes

