import math
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model that reproduces the collision outcomes recorded in the
    event list of a CLEVRER video.  The model uses the *inputs* argument
    to determine which objects are considered present; if the inputs list
    is empty, it treats every object defined in the video as present.
    Collisions that involve only present objects are returned as
    outcome records.

    Parameters
    ----------
    doc : dict
        The document tree.
    scope : str
        Title of the video (e.g. "Video 14863").
    inputs : list[dict]
        Input records (from `inputs()`).  Each record must contain a
        ``time`` and an ``entities`` list.  If empty, all objects are
        considered present.
    params : dict
        Unused for CLEVRER but accepted by signature.
    start : float | None
        First frame to consider.  Defaults to 0.0.
    horizon : float | None
        Last frame to consider.  Defaults to the last frame in the
        motion log of the video.

    Returns
    -------
    list[dict]
        Outcome records matching `outcomes()` structure.
    """
    # ---------- helpers ----------
    def _node_by_title(title):
        return node_by_title(doc, title)

    def _children(node):
        return children(doc, node)

    def _table_rows(node):
        return table_rows(node)

    # ---------- determine set of objects that are present ----------
    if inputs:
        # use only record times in inputs
        present_at: dict[str, float] = {}
        for rec in inputs:
            t = rec.get("time", 0.0)
            for oid in rec.get("entities", []):
                if oid not in present_at or t < present_at[oid]:
                    present_at[oid] = t
    else:
        # no input records: assume every object is present from the start
        present_at = None  # flag to indicate all objects are present

    # ---------- retrieve the Events node ----------
    ev_node = None
    for child in _children(_node_by_title(scope)):
        if child.get("kind") == "list" and "Events" in child.get("title", ""):
            ev_node = child
            break
    if ev_node is None:
        return []

    # ---------- simulation bounds ----------
    if start is None:
        start = 0.0
    if horizon is None:
        # find last frame in motion log
        mot_node = None
        for child in _children(_node_by_title(scope)):
            if child.get("kind") == "table" and "Motion log" in child.get("title", ""):
                mot_node = child
                break
        if mot_node:
