def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model that reproduces the collision outcomes recorded in the
    event list of a CLEVRER video.  The model uses the *inputs* argument
    to determine which objects are considered present; if the inputs list
    is empty, it treats every object defined in the video as present.
    Collisions that involve only present objects are returned as
    outcome records, mimicking the structure produced by `outcomes()`.

    Parameters
    ----------
    doc : dict
        The document tree.
    scope : str
        Title of the video (e.g. "Video 14863").
    inputs : list[dict]
        Input records (from `inputs()`).  Each record must contain a
        ``time`` and an ``entities`` list.  If the list is empty, every
        object from the video is considered present.
    params : dict
        Unused for CLEVRER but accepted by the signature.
    start : float | None
        First frame to consider.  Defaults to 0.0.
    horizon : float | None
        Last frame to consider.  Defaults to the last recorded frame in
        the motion log of the video.

    Returns
    -------
    list[dict]
        Outcome records matching the structure returned by `outcomes()`.
    """
    # ----------------------------------------------------------------------
    #  Helpers – thin wrappers around the sandbox helpers
    # ----------------------------------------------------------------------
    def _node_by_title(title):
        return node_by_title(doc, title)

    def _children(node):
        return children(doc, node)

    def _table_rows(node):
        return table_rows(node)

    # ----------------------------------------------------------------------
    #  Determine the set of objects that are present at the simulation start.
    # ----------------------------------------------------------------------
    if inputs:
        presence: dict[str, float] = {}
        for rec in inputs:
            t = rec.get("time", 0.0)
            for oid in rec.get("entities", []):
                if oid not in presence or t < presence[oid]:
                    presence[oid] = t
    else:
        presence = None  # flag meaning “every object is present”

    # ----------------------------------------------------------------------
    #  Locate the Events node for this video
    # ----------------------------------------------------------------------
    ev_node = None
    for child in _children(_node_by_title(scope)):
        if child.get("kind") == "list" and "Events" in child.get("title", ""):
            ev_node = child
            break
    if ev_node is None:
        return []

    # ----------------------------------------------------------------------
    #  Determine simulation bounds
    # ----------------------------------------------------------------------
    if start is None:
        start = 0.0
    if horizon is None:
        # horizon = last frame in motion log
        mot_node = None
        for child in _children(_node_by_title(scope)):
            if child.get("kind") == "table" and "Motion log" in child.get("title", ""):
                mot_node = child
                break
        if mot_node:
            horizon = max(_float_cast(row.get("frame", "0")) for _, row in _table_rows(mot_node))
        else:
            horizon = start

    # ----------------------------------------------------------------------
    #  Produce outcome records
    # ----------------------------------------------------------------------
    outcomes = []
    for idx, line in enumerate(ev_node.get("lines", [])):
        frame, kind, involved = _parse_event_line(line)
        if kind != "collision":
            continue
        if frame < start or frame > horizon:
            continue

        # If any involved object becomes present after this frame we ignore
        if presence is not None and any(presence.get(oid, float("inf")) > frame for oid in involved):
            continue

        outcomes.append(
            {
                "time": frame,
                "kind": "collision",
                "entities": list(involved),
                "value": None,
                "src": [[ev_node.get("node_id"), idx]],
            }
        )

    # Align with expected ordering
    outcomes.sort(key=lambda r: r["time"])
    return outcomes

