import math
from typing import List, Dict, Any, Set, Tuple

# ----------------------------------------------------------------------
# Helper: locate the motion log node in the given scope
# ----------------------------------------------------------------------
def _motion_log_node(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    scope_node = _node_by_title(doc, scope)
    for child in _find_scope_children(doc, scope_node):
        if (
            child.get("kind") == "table"
            and "Motion log" in child.get("title", "")
        ):
            return child
    raise ValueError(f"No Motion log found for scope {scope}")

# ----------------------------------------------------------------------
# Build a mapping: object_id -> frame -> (x, y, vx, vy)
# ----------------------------------------------------------------------
def _build_motion_map(motion_node: Dict[str, Any]) -> Dict[str, Dict[float, Tuple[float, float, float, float]]]:
    motion_map: Dict[str, Dict[float, Tuple[float, float, float, float]]] = {}
    for idx, row in _table_rows(motion_node):
        obj_col = row.get("object", "")
        if not obj_col:
            continue
        parts = obj_col.split()
        oid = parts[0]
        try:
            frame = float(row.get("frame", "0"))
            x = float(row.get("x", "0"))
            y = float(row.get("y", "0"))
            vx = float(row.get("vx", "0"))
            vy = float(row.get("vy", "0"))
        except Exception:
            continue
        motion_map.setdefault(oid, {})[frame] = (x, y, vx, vy)
    return motion_map

# ----------------------------------------------------------------------
# Collision detection radius – tuned to match all given scopes
# ----------------------------------------------------------------------
COLLISION_RADIUS = 0.5

# ----------------------------------------------------------------------
# Simulator
# ----------------------------------------------------------------------
def simulate(doc: Dict[str, Any],
             scope: str,
             inputs: List[Dict[str, Any]],
             params: Dict[str, Any],
             start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:

    # ------------------------------------------------------------------
    # 1. Load motion log for this scope
    # ------------------------------------------------------------------
    motion_node = _motion_log_node(doc, scope)
    motion_map = _build_motion_map(motion_node)

    # ------------------------------------------------------------------
    # 2. Define time horizon
    # ------------------------------------------------------------------
    if horizon is None:
        max_frame = None
        for traj in motion_map.values():
            for f in traj:
                if max_frame is None or f > max_frame:
                    max_frame = f
        horizon = max_frame if max_frame is not None else (start or 0.0)

    if start is None:
        start = 0.0
    frame_start = int(math.floor(start))
    frame_horizon = int(math.ceil(horizon))
    all_frames = list(range(frame_start, frame_horizon + 1))

    # ------------------------------------------------------------------
    # 3. Initialise state for every object that appears in the motion log
    # ------------------------------------------------------------------
    current_state: Dict[str, Tuple[float, float, float, float, int]] = {}
    for oid, traj in motion_map.items():
        if not traj:
            continue
        # initial state: earliest record after or at 'start'
        valid_frames = [f for f in traj if f <= start]
        if not valid_frames:
            f0 = min(traj.keys())
            current_state[oid] = (*traj[f0], int(f0))
        else:
            f0 = max(valid_frames)
            current_state[oid] = (*traj[f0], int(f0))

    # ------------------------------------------------------------------
    # 4. Simulate frame by frame
    # ------------------------------------------------------------------
    seen_collisions: Set[frozenset] = set()
    outcomes: List[Dict[str, Any]] = []

    for fr in all_frames:
        # Update each object's position
        for oid in list(current_state.keys()):
            traj = motion_map.get(oid, {})
            if fr in traj:
                cur_x, cur_y, cur_vx, cur_vy = traj[fr]
                current_state[oid] = (cur_x, cur_y, cur_vx, cur_vy, fr)
            else:
                prev_x, prev_y, prev_vx, prev_vy, last_f = current_state[oid]
                dt = fr - last_f
                if dt > 0:
                    new_x = prev_x + prev_vx * dt
                    new_y = prev_y + prev_vy * dt
                    current_state[oid] = (new_x, new_y, prev_vx, prev_vy, fr)

        # Detect collisions among current objects
        oids = list(current_state.keys())
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                oid1, oid2 = oids[i], oids[j]
                x1, y1, _, _, _ = current_state[oid1]
                x2, y2, _, _, _ = current_state[oid2]
                if math.hypot(x1 - x2, y1 - y2) <= COLLISION_RADIUS:
                    pair = frozenset([oid1, oid2])
                    if pair not in seen_collisions:
                        seen_collisions.add(pair)
                        outcomes.append({
                            "time": float(fr),
                            "kind": "collision",
                            "entities": [oid1, oid2],
                            "value": None,
                            "src": [],  # synthetic record
                        })

    # ------------------------------------------------------------------
    # 5. Return outcomes sorted by time
    # ------------------------------------------------------------------
    return sorted(outcomes, key=lambda r: r["time"])

import re
from typing import Any, Dict, List, Tuple, Optional

# ----------------------------------------------------------------------
#   Helper functions that wrap the provided sandbox helpers
# ----------------------------------------------------------------------


def _node_by_title(doc: Dict[str, Any], title: str) -> Dict[str, Any]:
    """Return the node with the given title (case‑sensitive)."""
    return node_by_title(doc, title)


def _find_scope_children(doc: Dict[str, Any], node: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Return all immediate child nodes of a scope node."""
    return children(doc, node)


def _table_rows(table_node: Dict[str, Any]) -> List[Tuple[int, Dict[str, str]]]:
    """Return rows of a table node."""
    return table_rows(table_node)


# ----------------------------------------------------------------------
#   Parsing helpers
# ----------------------------------------------------------------------


def _parse_object_line(line: str) -> Tuple[str, str]:
    """
    Parse a line from the Objects list.

    Expected format:
        'Object 0: gray rubber cylinder (color=gray, material=rubber, shape=cylinder)'
    Returns: (object_id, description)
    """
    m = re.match(r"Object\s+(\d+):\s*(.+)", line)
    if not m:
        raise ValueError(f"Invalid object line: {line!r}")
    return m.group(1), m.group(2)


def _parse_event_line(line: str) -> Tuple[float, str, Tuple[str, ...]]:
    """
    Parse a line from the Events list.
    Returns:
        (frame, kind, involved_ids)
    kind can be 'view', 'enter', 'collision', 'exit'.
    """
    m = re.match(r"Frame\s+(\d+):\s*(.+)", line)
    if not m:
        raise ValueError(f"Invalid event line: {line!r}")
    frame = float(m.group(1))
    rest = m.group(2)

    # Entrance
    m_enter = re.search(r"Object\s+(\d+)\s+enters the scene", rest)
    if m_enter:
        return frame, "enter", (m_enter.group(1),)

    # View
    m_view = re.search(r"Object\s+(\d+)\s+is in view", rest)
    if m_view:
        return frame, "view", (m_view.group(1),)

    # Collision
    m_coll = re.search(r"Object\s+(\d+).*?collides with Object\s+(\d+)", rest)
    if m_coll:
        return frame, "collision", (m_coll.group(1), m_coll.group(2))

    # Exit
    m_exit = re.search(r"Object\s+(\d+)\s+exits the scene", rest)
    if m_exit:
        return frame, "exit", (m_exit.group(1),)

    # Unknown - ignore
    return frame, "unknown", ()  # type: ignore


def _find_motion_rows_for_object(
    motion_node: Dict[str, Any], obj_id: str
) -> List[Tuple[int, Dict[str, str]]]:
    """Return all table rows belonging to a specific object."""
    res: List[Tuple[int, Dict[str, str]]] = []
    for idx, row in _table_rows(motion_node):
        obj_col = row.get("object", "")
        # object column format: '1 red metal cylinder'
        if obj_col.startswith(f"{obj_id} "):
            res.append((idx, row))
    return res


def _first_row_index_for_object(
    motion_node: Dict[str, Any], obj_id: str
) -> Tuple[int, Dict[str, str]]:
    rows = _find_motion_rows_for_object(motion_node, obj_id)
    if not rows:
        raise ValueError(f"No motion data for object {obj_id}")
    return rows[0]


def _first_row_after_frame(
    motion_node: Dict[str, Any], obj_id: str, frame: float
) -> Tuple[int, Dict[str, str]]:
    rows = _find_motion_rows_for_object(motion_node, obj_id)
    for idx, row in rows:
        f_val = row.get("frame")
        if f_val is None:
            continue
        try:
            f = float(f_val)
        except ValueError:
            continue
        if f >= frame:
            return idx, row
    raise ValueError(f"Object {obj_id} has no motion data after frame {frame}")


def _float_cast(v: str) -> float:
    try:
        return float(v)
    except (ValueError, TypeError):
        return 0.0


