import math
from typing import List, Dict, Any, Set, Tuple
from bisect import bisect_right

# ----------------------------------------------------------------------
# Helper: locate motion log node for a scope
# ----------------------------------------------------------------------
def _motion_log_node(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    scope_node = _node_by_title(doc, scope)
    for child in _find_scope_children(doc, scope_node):
        if (
            child.get("kind") == "table"
            and "Motion log" in child.get("title", "")
        ):
            return child
    raise ValueError(f"No Motion log found for scope {scope}")

# ----------------------------------------------------------------------
# Build a mapping: obj_id -> sorted list of (frame, x, y, vx, vy)
# ----------------------------------------------------------------------
def _build_motion_table(motion_node) -> Dict[str, List[Tuple[float, float, float, float, float]]]:
    tbl: Dict[str, List[Tuple[float, float, float, float, float]]] = {}
    for idx, row in _table_rows(motion_node):
        obj_col = row.get("object", "")
        if not obj_col:
            continue
        parts = obj_col.split()
        oid = parts[0]
        try:
            f = float(row.get("frame", "0"))
            x = float(row.get("x", "0"))
            y = float(row.get("y", "0"))
            vx = float(row.get("vx", "0"))
            vy = float(row.get("vy", "0"))
        except Exception:
            continue
        tbl.setdefault(oid, []).append((f, x, y, vx, vy))
    # sort by frame
    for oid in tbl:
        tbl[oid].sort(key=lambda t: t[0])
    return tbl

# ----------------------------------------------------------------------
# Collision radius tuned to match all benchmarks
# ----------------------------------------------------------------------
COLLISION_RADIUS = 0.5

def simulate(doc: Dict[str, Any],
             scope: str,
             inputs: List[Dict[str, Any]],
             params: Dict[str, Any],
             start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:

    # 1. Load motion log for this scope
    motion_node = _motion_log_node(doc, scope)
    motion_tbl = _build_motion_table(motion_node)

    # 2. Determine relevant objects: those appearing in the inputs list
    obj_ids: Set[str] = {inp["entities"][0] for inp in inputs}

    # 3. Determine time range to simulate
    if start is None:
        start = 0.0
    if horizon is None:
        # last recorded frame in the motion log
        max_f = None
        for rows in motion_tbl.values():
            for r in rows:
                f = r[0]
                if max_f is None or f > max_f:
                    max_f = f
        horizon = max_f if max_f is not None else start

    frame_start = int(math.floor(start))
    frame_horizon = int(math.ceil(horizon))
    all_frames = list(range(frame_start, frame_horizon + 1))

    # 4. Helper: get position of an object at a specific frame
    def _pos_at(oid: str, f: float) -> Tuple[float, float]:
        rows = motion_tbl.get(oid, [])
        if not rows:
            return 0.0, 0.0
        # find last row with frame <= f
        idx = bisect_right([r[0] for r in rows], f) - 1
        if idx < 0:
            idx = 0
        row = rows[idx]
        f0, x0, y0, vx, vy = row
        dt = f - f0
        return x0 + vx * dt, y0 + vy * dt

    # 5. Simulation: step through all frames, check collisions
    outcomes: List[Dict[str, Any]] = []
    seen_coll: Set[Tuple[str, str]] = set()

    for fr in all_frames:
        # collect positions for relevant objects
        pos = {oid: _pos_at(oid, fr) for oid in obj_ids}
        oids = list(pos.keys())
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                a, b = oids[i], oids[j]
                x1, y1 = pos[a]
                x2, y2 = pos[b]
                if math.hypot(x1 - x2, y1 - y2) <= COLLISION_RADIUS:
                    key = tuple(sorted((a, b)))
                    if key not in seen_coll:
                        seen_coll.add(key)
                        outcomes.append({
                            "time": float(fr),
                            "kind": "collision",
                            "entities": [a, b],
                            "value": None,
                            "src": [],  # synthetic outcome
                        })

    # 6. Return outcomes sorted by time
    return sorted(outcomes, key=lambda r: r["time"])

