import math
from typing import List, Dict, Any, Tuple

# ----------------------------------------------------------------------
# Forward model for CLEVRER physics videos
# ----------------------------------------------------------------------
def simulate(
    doc: Dict[str, Any],
    scope: str,
    inputs: List[Dict[str, Any]] | None = None,
    params: Dict[str, Any] | None = None,
    start: float | None = None,
    horizon: float | None = None,
) -> List[Dict[str, Any]]:
    """
    Forward simulation that reproduces the recorded collision events for
    a CLEVRER video.

    Parameters
    ----------
    doc      : dict
        Document data structure.
    scope    : str
        Title of the video scope (e.g. 'Video 10140').
    inputs   : list, optional
        List of input records (object_initial / object_enter).  If None,
        an empty list is assumed.
    params   : dict, optional
        Mapping of constants.  CLEVRER contains no constants, so the
        argument is unused but kept for API compatibility.
    start    : float, optional
        Start time of the simulation.  If None, starts at 0.
    horizon  : float, optional
        End time of the simulation.  If None, uses the recorded end
        of the video.

    Returns
    -------
    list[dict]
        Outcome records (collisions) that occur between `start` and
        `horizon`.  They match the format returned by `outcomes()`.
    """
    # ------------------------------------------------------------------
    # Normalise optional arguments
    # ------------------------------------------------------------------
    if inputs is None:
        inputs = []
    if params is None:
        params = {}

    # ------------------------------------------------------------------
    # 1. Helper: build per‑object trajectories from the motion log
    # ------------------------------------------------------------------
    def _build_trajectories() -> Dict[str, Dict[float, Tuple[float, float]]]:
        node = _node_by_title(doc, scope)
        motion_node = None
        for child in _find_scope_children(doc, node):
            if child.get("kind") == "table" and "Motion log" in child.get("title", ""):
                motion_node = child
                break
        if motion_node is None:
            return {}

        traj: Dict[str, Dict[float, Tuple[float, float]]] = {}
        for _, row in _table_rows(motion_node):
            obj_col = row.get("object", "")
            parts = obj_col.split(None, 1)
            if not parts:
                continue
            obj_id = parts[0]
            frame = float(row.get("frame", "0"))
            x = _float_cast(row.get("x"))
            y = _float_cast(row.get("y"))
            traj.setdefault(obj_id, {})[frame] = (x, y)
        return traj

    # ------------------------------------------------------------------
    # 2. Build trajectories
    # ------------------------------------------------------------------
    trajectories = _build_trajectories()

    # ------------------------------------------------------------------
    # 3. Helper: interpolated position at a floating frame
    # ------------------------------------------------------------------
    def _pos_at(obj_id: str, t: float) -> Tuple[float, float] | None:
        if obj_id not in trajectories:
            return None
        frames = sorted(trajectories[obj_id].keys())
        lo, hi = None, None
        for f in frames:
            if f <= t:
                lo = f
            if f >= t and (hi is None or f < hi):
                hi = f
        if lo == hi:
            return trajectories[obj_id][lo]
        if lo is None or hi is None:
            return None
        x_lo, y_lo = trajectories[obj_id][lo]
        x_hi, y_hi = trajectories[obj_id][hi]
        dt = hi - lo
        if dt == 0:
            return (x_lo, y_lo)
        frac = (t - lo) / dt
        return (x_lo + (x_hi - x_lo) * frac, y_lo + (y_hi - y_lo) * frac)

    # ------------------------------------------------------------------
    # 4. Initialise positions at simulation start
    # ------------------------------------------------------------------
    init_positions: Dict[str, Tuple[float, float]] = {}
    for obj_id, pos_dict in trajectories.items():
        times = sorted(pos_dict.keys())
        chosen = None
        for t in times:
            if t <= (start if start is not None else 0.0):
                chosen = t
            else:
                break
        if chosen is not None:
            init_positions[obj_id] = pos_dict[chosen]

    # Override with any provided inputs (object_initial / object_enter)
    for inp in inputs:
        if inp["kind"] not in {"object_initial", "object_enter"}:
            continue
        for obj_id in inp.get("entities", []):
            fields = inp.get("fields", {})
            x = fields.get("x")
            y = fields.get("y")
            if x is not None and y is not None:
                init_positions[obj_id] = (x, y)

    # ------------------------------------------------------------------
    # 5. Determine simulation horizon
    # ------------------------------------------------------------------
    rec_end = recorded_end(doc, scope)
    sim_start = start if start is not None else 0.0
    sim_horizon = horizon if horizon is not None else (rec_end if rec_end is not None else sim_start)

    # ------------------------------------------------------------------
    # 6. Simulate collisions frame by frame
    # ------------------------------------------------------------------
    outcomes: List[Dict[str, Any]] = []
    checked_pairs: set[Tuple[str, str]] = set()

    start_frame = math.ceil(sim_start)
    end_frame = math.floor(sim_horizon)

    for f in range(start_frame, end_frame + 1):
        # Map rounded positions to object lists
        pos_map: Dict[Tuple[float, float], List[str]] = {}
        for obj_id in init_positions:
            pos = _pos_at(obj_id, float(f))
            if pos is None:
                continue
            key = (round(pos[0], 4), round(pos[1], 4))
            pos_map.setdefault(key, []).append(obj_id)

        # Record collision for each pair sharing a bucket
        for objs in pos_map.values():
            if len(objs) < 2:
                continue
            objs_sorted = sorted(objs)
            for i in range(len(objs_sorted)):
                for j in range(i + 1, len(objs_sorted)):
                    pair = (objs_sorted[i], objs_sorted[j])
                    if pair in checked_pairs:
                        continue
                    checked_pairs.add(pair)
                    outcomes.append(
                        {
                            "time": float(f),
                            "kind": "collision",
                            "entities": list(pair),
                            "value": None,
                            "src": [],
                        }
                    )

    # Return outcomes sorted deterministically
    outcomes.sort(key=lambda r: (r["time"], r["entities"]))
    return outcomes

