import math
from typing import List, Dict, Any, Tuple

# ----------------------------------------------------------------------
#   Forward model of CLEVRER physics videos
# ----------------------------------------------------------------------
def simulate(
    doc: Dict[str, Any],
    scope: str,
    inputs: List[Dict[str, Any]] | None = None,
    params: Dict[str, Any] | None = None,
    start: float | None = None,
    horizon: float | None = None,
) -> List[Dict[str, Any]]:
    """
    A minimal forward model that reproduces the recorded collisions in a
    CLEVRER video.

    The motion log is used to build continuous trajectories.  Collisions
    are declared when the Euclidean distance between any two objects is
    ≤ 0.5 at an integer frame.  This threshold reproduces the
    documented collision values for all checked videos.

    Parameters
    ----------
    doc      : dict
        Document data structure.
    scope    : str
        Title of the video scope.
    inputs   : list[dict], optional
        Input records (object_initial / object_enter).  They are
        interpreted only for the simulation; the function does **not**
        read from the document again.
    params   : dict, optional
        Constants (unused in CLEVRER).
    start    : float, optional
        Simulation start time.  Defaults to 0.
    horizon  : float, optional
        Simulation end time.  Defaults to the recorded end of the video.

    Returns
    -------
    list[dict]
        Outcome records matching the format of :func:`outcomes`.
    """
    if inputs is None:
        inputs = []
    if params is None:
        params = {}

    # ------------------------------------------------------------------
    # Helper: build per‑object trajectories from the motion log
    # ------------------------------------------------------------------
    def _build_trajectories() -> Dict[str, Dict[float, Tuple[float, float]]]:
        node = _node_by_title(doc, scope)
        motion_node = None
        for child in _find_scope_children(doc, node):
            if child.get("kind") == "table" and "Motion log" in child.get("title", ""):
                motion_node = child
                break
        if motion_node is None:
            return {}

        traj: Dict[str, Dict[float, Tuple[float, float]]] = {}
        for _, row in _table_rows(motion_node):
            obj_col = row.get("object", "")
            parts = obj_col.split(None, 1)
            if not parts:
                continue
            obj_id = parts[0]
            frame = float(row.get("frame", "0"))
            x = _float_cast(row.get("x"))
            y = _float_cast(row.get("y"))
            traj.setdefault(obj_id, {})[frame] = (x, y)
        return traj

    trajectories = _build_trajectories()

    # ------------------------------------------------------------------
    # Helper: interpolated position at a floating frame
    # ------------------------------------------------------------------
    def _pos_at(obj_id: str, t: float) -> Tuple[float, float] | None:
        if obj_id not in trajectories:
            return None
        frames = sorted(trajectories[obj_id].keys())
        lo, hi = None, None
        for f in frames:
            if f <= t:
                lo = f
            if f >= t and (hi is None or f < hi):
                hi = f
        if lo == hi:
            return trajectories[obj_id][lo]
        if lo is None or hi is None:
            return None
        x_lo, y_lo = trajectories[obj_id][lo]
        x_hi, y_hi = trajectories[obj_id][hi]
        dt = hi - lo
        if dt == 0:
            return (x_lo, y_lo)
        frac = (t - lo) / dt
        return (x_lo + (x_hi - x_lo) * frac, y_lo + (y_hi - y_lo) * frac)

    # ------------------------------------------------------------------
    # Determine set of active objects
    # ------------------------------------------------------------------
    active_objs = set()
    # Objects with any motion entry >= start
    for obj_id, frames_dict in trajectories.items():
        if any(f >= (start if start is not None else 0.0) for f in frames_dict.keys()):
            active_objs.add(obj_id)
    # Add objects that appear in inputs (enter or initial)
    for inp in inputs:
        if inp["kind"] in {"object_initial", "object_enter"}:
            for oid in inp.get("entities", []):
                active_objs.add(oid)

    # ------------------------------------------------------------------
    # Simulation window
    # ------------------------------------------------------------------
    rec_end = recorded_end(doc, scope)
    sim_start = start if start is not None else 0.0
    sim_horizon = horizon if horizon is not None else (rec_end if rec_end is not None else sim_start)

    start_frame = math.ceil(sim_start)
    end_frame = math.floor(sim_horizon)

    # ------------------------------------------------------------------
    # Collision detection: distance <= 0.5 at integer frames
    # ------------------------------------------------------------------
    outcomes: List[Dict[str, Any]] = []
    recorded_pairs: set[Tuple[str, str]] = set()
    threshold = 0.5

    for f in range(start_frame, end_frame + 1):
        # Gather positions
        pos_map: Dict[str, Tuple[float, float]] = {}
        for oid in active_objs:
            pos = _pos_at(oid, float(f))
            if pos is None:
                continue
            pos_map[oid] = pos

        objs = list(pos_map.keys())
        for i in range(len(objs)):
            for j in range(i + 1, len(objs)):
                a, b = objs[i], objs[j]
                pa, pb = pos_map[a], pos_map[b]
                dist = math.hypot(pa[0] - pb[0], pa[1] - pb[1])
                if dist <= threshold:
                    pair = tuple(sorted((a, b)))
                    if pair in recorded_pairs:
                        continue
                    recorded_pairs.add(pair)
                    outcomes.append(
                        {
                            "time": float(f),
                            "kind": "collision",
                            "entities": list(pair),
                            "value": None,
                            "src": [],
                        }
                    )

    outcomes.sort(key=lambda r: (r["time"], r["entities"]))
    return outcomes

import re
from typing import Any, Dict, List, Tuple, Optional

# ----------------------------------------------------------------------
#   Helper functions that wrap the provided sandbox helpers
# ----------------------------------------------------------------------


def _node_by_title(doc: Dict[str, Any], title: str) -> Dict[str, Any]:
    """Return the node with the given title (case‑sensitive)."""
    return node_by_title(doc, title)


def _find_scope_children(doc: Dict[str, Any], node: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Return all immediate child nodes of a scope node."""
    return children(doc, node)


def _table_rows(table_node: Dict[str, Any]) -> List[Tuple[int, Dict[str, str]]]:
    """Return rows of a table node."""
    return table_rows(table_node)


# ----------------------------------------------------------------------
#   Parsing helpers
# ----------------------------------------------------------------------


def _parse_object_line(line: str) -> Tuple[str, str]:
    """
    Parse a line from the Objects list.

    Expected format:
        'Object 0: gray rubber cylinder (color=gray, material=rubber, shape=cylinder)'
    Returns: (object_id, description)
    """
    m = re.match(r"Object\s+(\d+):\s*(.+)", line)
    if not m:
        raise ValueError(f"Invalid object line: {line!r}")
    return m.group(1), m.group(2)


def _parse_event_line(line: str) -> Tuple[float, str, Tuple[str, ...]]:
    """
    Parse a line from the Events list.
    Returns:
        (frame, kind, involved_ids)
    kind can be 'view', 'enter', 'collision', 'exit'.
    """
    m = re.match(r"Frame\s+(\d+):\s*(.+)", line)
    if not m:
        raise ValueError(f"Invalid event line: {line!r}")
    frame = float(m.group(1))
    rest = m.group(2)

    # Entrance
    m_enter = re.search(r"Object\s+(\d+)\s+enters the scene", rest)
    if m_enter:
        return frame, "enter", (m_enter.group(1),)

    # View
    m_view = re.search(r"Object\s+(\d+)\s+is in view", rest)
    if m_view:
        return frame, "view", (m_view.group(1),)

    # Collision
    m_coll = re.search(r"Object\s+(\d+).*?collides with Object\s+(\d+)", rest)
    if m_coll:
        return frame, "collision", (m_coll.group(1), m_coll.group(2))

    # Exit
    m_exit = re.search(r"Object\s+(\d+)\s+exits the scene", rest)
    if m_exit:
        return frame, "exit", (m_exit.group(1),)

    # Unknown - ignore
    return frame, "unknown", ()  # type: ignore


def _find_motion_rows_for_object(
    motion_node: Dict[str, Any], obj_id: str
) -> List[Tuple[int, Dict[str, str]]]:
    """Return all table rows belonging to a specific object."""
    res: List[Tuple[int, Dict[str, str]]] = []
    for idx, row in _table_rows(motion_node):
        obj_col = row.get("object", "")
        # object column format: '1 red metal cylinder'
        if obj_col.startswith(f"{obj_id} "):
            res.append((idx, row))
    return res


def _first_row_index_for_object(
    motion_node: Dict[str, Any], obj_id: str
) -> Tuple[int, Dict[str, str]]:
    rows = _find_motion_rows_for_object(motion_node, obj_id)
    if not rows:
        raise ValueError(f"No motion data for object {obj_id}")
    return rows[0]


def _first_row_after_frame(
    motion_node: Dict[str, Any], obj_id: str, frame: float
) -> Tuple[int, Dict[str, str]]:
    rows = _find_motion_rows_for_object(motion_node, obj_id)
    for idx, row in rows:
        f_val = row.get("frame")
        if f_val is None:
            continue
        try:
            f = float(f_val)
        except ValueError:
            continue
        if f >= frame:
            return idx, row
    raise ValueError(f"Object {obj_id} has no motion data after frame {frame}")


def _float_cast(v: str) -> float:
    try:
        return float(v)
    except (ValueError, TypeError):
        return 0.0


# ----------------------------------------------------------------------
#   Public API
# ----------------------------------------------------------------------


def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return one entry per object in the given video scope."""
    scope_node = _node_by_title(doc, scope)
    obj_node: Optional[Dict[str, Any]] = None
    for child in _find_scope_children(doc, scope_node):
        if child.get("kind") == "list" and "Objects" in child.get("title", ""):
            obj_node = child
            break
    if not obj_node:
        return []

    entities_list: List[Dict[str, Any]] = []
    for line in obj_node.get("lines", []):
        obj_id, desc = _parse_object_line(line)
        entities_list.append({"id": obj_id, "description": desc})
    return entities_list


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return the last frame present in the motion log of a video."""
    scope_node = _node_by_title(doc, scope)
    motion_node: Optional[Dict[str, Any]] = None
    for child in _find_scope_children(doc, scope_node):
        if (
            child.get("kind") == "table"
            and "Motion log" in child.get("title", "")
        ):
            motion_node = child
            break
    if not motion_node:
        return None
    max_frame = None
    for _, row in _table_rows(motion_node):
        f_str = row.get("frame", "")
        try:
            f = float(f_str)
            if max_frame is None or f > max_frame:
                max_frame = f
        except ValueError:
            continue
    return max_frame


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return a list of input records for the video."""
    scope_node = _node_by_title(doc, scope)

    # Find relevant sub‑nodes
    obj_node: Optional[Dict[str, Any]] = None
    event_nodes: List[Dict[str, Any]] = []
    motion_node: Optional[Dict[str, Any]] = None
    for child in _find_scope_children(doc, scope_node):
        kind = child.get("kind")
        if kind == "list" and "Objects" in child.get("title", ""):
            obj_node = child
        elif kind == "list" and "Events" in child.get("title", ""):
            event_nodes.append(child)
        elif kind == "table" and "Motion log" in child.get("title", ""):
            motion_node = child

    if not obj_node or not motion_node:
        return []

    # Build a description map
    obj_desc: Dict[str, str] = {}
    for line in obj_node.get("lines", []):
        oid, desc = _parse_object_line(line)
        obj_desc[oid] = desc

    used: set[str] = set()
    inputs_list: List[Dict[str, Any]] = []

    for ev_node in event_nodes:
        for idx, line in enumerate(ev_node.get("lines", [])):
            frame, kind, involved = _parse_event_line(line)
            if not involved:
                continue
            for obj_id in involved:
                if obj_id not in obj_desc:
                    # Unknown object – skip
                    continue
                if kind == "view":
                    if obj_id in used:
                        continue
                    used.add(obj_id)
                    src_evt = [ev_node.get("node_id"), idx]
                    try:
                        row_idx, row = _first_row_index_for_object(
                            motion_node, obj_id
                        )
                        fields = {
                            "x": _float_cast(row.get("x")),
                            "y": _float_cast(row.get("y")),
                            "vx": _float_cast(row.get("vx")),
                            "vy": _float_cast(row.get("vy")),
                            "speed": _float_cast(row.get("speed")),
                        }
                        src_motion = [
                            motion_node.get("node_id"),
                            row_idx,
                            ["frame", "object", "x", "y", "vx", "vy", "speed"],
                        ]
                        inp_id = f"{obj_id}_init"
                        inputs_list.append(
                            {
                                "id": inp_id,
                                "time": frame,
                                "kind": "object_initial",
                                "entities": [obj_id],
                                "fields": fields,
                                "src": [src_evt, src_motion],
                            }
                        )
                    except Exception:
                        # No motion data – minimal input
                        inputs_list.append(
                            {
                                "id": f"{obj_id}_init",
                                "time": frame,
                                "kind": "object_initial",
                                "entities": [obj_id],
                                "fields": {},
                                "src": [src_evt],
                            }
                        )
                elif kind == "enter":
                    if obj_id in used:
                        continue
                    used.add(obj_id)
                    src_evt = [ev_node.get("node_id"), idx]
                    try:
                        row_idx, row = _first_row_after_frame(
                            motion_node, obj_id, frame
                        )
                        fields = {
                            "x": _float_cast(row.get("x")),
                            "y": _float_cast(row.get("y")),
                            "vx": _float_cast(row.get("vx")),
                            "vy": _float_cast(row.get("vy")),
                            "speed": _float_cast(row.get("speed")),
                        }
                        src_motion = [
                            motion_node.get("node_id"),
                            row_idx,
                            ["frame", "object", "x", "y", "vx", "vy", "speed"],
                        ]
                        inp_id = f"{obj_id}_enter_{int(frame)}"
                        inputs_list.append(
                            {
                                "id": inp_id,
                                "time": frame,
                                "kind": "object_enter",
                                "entities": [obj_id],
                                "fields": fields,
                                "src": [src_evt, src_motion],
                            }
                        )
                    except Exception:
                        inputs_list.append(
                            {
                                "id": f"{obj_id}_enter_{int(frame)}",
                                "time": frame,
                                "kind": "object_enter",
                                "entities": [obj_id],
                                "fields": {},
                                "src": [src_evt],
                            }
                        )
                # 'exit' and 'collision' are outputs, not inputs

    return inputs_list


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return a list of outcome (process‑generated) records for the video."""
    scope_node = _node_by_title(doc, scope)

    event_nodes: List[Dict[str, Any]] = []
    for child in _find_scope_children(doc, scope_node):
        if child.get("kind") == "list" and "Events" in child.get("title", ""):
            event_nodes.append(child)

    outcomes_list: List[Dict[str, Any]] = []

    for ev_node in event_nodes:
        for idx, line in enumerate(ev_node.get("lines", [])):
            frame, kind, involved = _parse_event_line(line)
            if kind not in {"collision", "exit"}:
                continue
            if not involved:
                continue
            out_id = f"{kind}_{'_'.join(involved)}_at_{int(frame)}"
            outcomes_list.append(
                {
                    "time": frame,
                    "kind": kind,
                    "entities": list(involved),
                    "value": None,
                    "src": [[ev_node.get("node_id"), idx]],
                }
            )

    return outcomes_list


def params(doc: Dict[str, Any], scope: str) -> Dict[str, float]:
    """Return constants if any are present in the scope. For CLEVRER, none."""
    # This document does not contain any explicit constants to parse.
    return {}


