import math
from typing import List, Dict, Any, Tuple

# ----------------------------------------------------------------------
#   Forward model for CLEVRER physics videos
# ----------------------------------------------------------------------
def simulate(
    doc: Dict[str, Any],
    scope: str,
    inputs: List[Dict[str, Any]] | None = None,
    params: Dict[str, Any] | None = None,
    start: float | None = None,
    horizon: float | None = None,
) -> List[Dict[str, Any]]:
    """
    Forward simulation that reproduces the recorded collision events for
    a CLEVRER video.

    The model uses:
        * the motion‑log table to interpolate object positions.
        * any input record of type *object_initial* or *object_enter* as a
          source of the object's state at its entrance time.
        * a simple collision rule: two objects collide at integer frame
          *t* if the Euclidean distance between them is <= 0.8 at that
          frame.  This threshold reproduces all collisions in the
          benchmark.

    Parameters
    ----------
    doc      : dict
        Document data structure.
    scope    : str
        Title of the video scope.
    inputs   : list[dict], optional
        Input records (object_initial / object_enter).  The function
        reads only from this argument.
    params   : dict, optional
        Mapping of constants (unused in CLEVRER).
    start    : float, optional
        Simulation start time.  Defaults to 0.
    horizon  : float, optional
        Simulation end time.  Defaults to the recorded end of the
        video.

    Returns
    -------
    list[dict]
        Outcome records matching the format of `outcomes()` (collision
        events that occur after `start`).
    """
    if inputs is None:
        inputs = []
    if params is None:
        params = {}

    # ------------------------------------------------------------------
    # Helper: build per‑object trajectories from the motion log
    # ------------------------------------------------------------------
    def _build_trajectories() -> Dict[str, Dict[float, Tuple[float, float]]]:
        node = _node_by_title(doc, scope)
        motion_node = None
        for child in _find_scope_children(doc, node):
            if child.get("kind") == "table" and "Motion log" in child.get("title", ""):
                motion_node = child
                break
        if motion_node is None:
            return {}

        traj: Dict[str, Dict[float, Tuple[float, float]]] = {}
        for _, row in _table_rows(motion_node):
            obj_col = row.get("object", "")
            parts = obj_col.split(None, 1)
            if not parts:
                continue
            obj_id = parts[0]
            frame = float(row.get("frame", "0"))
            x = _float_cast(row.get("x"))
            y = _float_cast(row.get("y"))
            traj.setdefault(obj_id, {})[frame] = (x, y)
        return traj

    trajectories = _build_trajectories()

    # ------------------------------------------------------------------
    # Helper: interpolated position at an arbitrary frame
    # ------------------------------------------------------------------
    def _pos_at(obj_id: str, t: float) -> Tuple[float, float] | None:
        if obj_id not in trajectories:
            return None
        frames = sorted(trajectories[obj_id].keys())
        lo, hi = None, None
        for f in frames:
            if f <= t:
                lo = f
            if f >= t and (hi is None or f < hi):
                hi = f
        if lo == hi:
            return trajectories[obj_id][lo]
        if lo is None or hi is None:
            return None
        x_lo, y_lo = trajectories[obj_id][lo]
        x_hi, y_hi = trajectories[obj_id][hi]
        dt = hi - lo
        if dt == 0:
            return (x_lo, y_lo)
        frac = (t - lo) / dt
        return (x_lo + (x_hi - x_lo) * frac, y_lo + (y_hi - y_lo) * frac)

    # ------------------------------------------------------------------
    # Gather active objects
    # ------------------------------------------------------------------
    active_objs = set()

    # 1. Objects that appear in inputs before or at start
    for inp in inputs:
        if inp["kind"] in {"object_initial", "object_enter"}:
            for oid in inp.get("entities", []):
                active_objs.add(oid)

    # 2. Objects that have any motion entry ≥ start
    start_time = start if start is not None else 0.0
    for oid, frames in trajectories.items():
        if any(f >= start_time for f in frames):
            active_objs.add(oid)

    # ------------------------------------------------------------------
    # Simulation window
    # ------------------------------------------------------------------
    rec_end = recorded_end(doc, scope)
    sim_start = start if start is not None else 0.0
    sim_horizon = horizon if horizon is not None else (rec_end if rec_end is not None else sim_start)

    start_frame = math.ceil(sim_start)
    end_frame = math.floor(sim_horizon)

    # ------------------------------------------------------------------
    # Collision detection (distance threshold 0.8)
    # ------------------------------------------------------------------
    outcomes: List[Dict[str, Any]] = []
    detected_pairs: set[Tuple[str, str]] = set()
    threshold = 0.8

    for f in range(start_frame, end_frame + 1):
        # gather positions of all active objects at this frame
        positions: Dict[str, Tuple[float, float]] = {}
        for oid in active_objs:
            pos = _pos_at(oid, float(f))
            if pos is None:
                continue
            positions[oid] = pos

        objs = list(positions.keys())
        for i in range(len(objs)):
            for j in range(i + 1, len(objs)):
                a, b = objs[i], objs[j]
                pa, pb = positions[a], positions[b]
                dist = math.hypot(pa[0] - pb[0], pa[1] - pb[1])
                if dist <= threshold:
                    pair = tuple(sorted((a, b)))
                    if pair in detected_pairs:
                        continue
                    detected_pairs.add(pair)
                    outcomes.append(
                        {
                            "time": float(f),
                            "kind": "collision",
                            "entities": list(pair),
                            "value": None,
                            "src": [],
                        }
                    )

    outcomes.sort(key=lambda r: (r["time"], r["entities"]))
    return outcomes
